//! The canonical Origin OS release identity (CLAUDE.md §62–§63).
//!
//! Every constant except [`PRODUCT`] is generated by `build.rs` from the repository's
//! `origin-version.toml`, the only place a version is written by hand. The release version
//! and the compatibility identifiers are independent numbers (ONBF-R8).
#![cfg_attr(not(test), no_std)]
#![forbid(unsafe_code)]

/// Product name.
pub const PRODUCT: &str = "Origin OS";

include!(concat!(env!("OUT_DIR"), "/origin_version.rs"));

#[cfg(test)]
#[path = "../manifest.rs"]
mod manifest;

#[cfg(test)]
mod tests {
    use super::manifest::{SemVer, parse};
    use super::*;

    const VALID: &str = r#"
# comment
[release]
version = "1.2.3-rc.1"   # trailing comment
build = 42
security-version = 7

[compatibility]
onbf-format = "1.0"
boot-info = "0.1"
"#;

    /// Replaces the first occurrence of `from` in [`VALID`].
    fn variant(from: &str, to: &str) -> String {
        assert!(VALID.contains(from), "{from:?} not in VALID");
        VALID.replacen(from, to, 1)
    }

    fn error_of(text: &str) -> String {
        parse(text).expect_err("expected a parse error")
    }

    #[test]
    fn generated_constants_match_the_repository_file() {
        let m = parse(include_str!("../../../origin-version.toml"))
            .expect("origin-version.toml is valid");
        assert_eq!(m.version.text(), VERSION);
        assert_eq!(
            (m.version.major, m.version.minor, m.version.patch),
            (VERSION_MAJOR, VERSION_MINOR, VERSION_PATCH)
        );
        assert_eq!(m.version.pre, VERSION_PRE);
        assert_eq!(m.build, BUILD);
        assert_eq!(m.security_version, SECURITY_VERSION);
        assert_eq!(m.onbf_format, (ONBF_FORMAT_MAJOR, ONBF_FORMAT_MINOR));
        assert_eq!(m.boot_info, (BOOT_INFO_MAJOR, BOOT_INFO_MINOR));
    }

    #[test]
    fn parses_a_valid_file() {
        let m = parse(VALID).unwrap();
        assert_eq!(
            m.version,
            SemVer {
                major: 1,
                minor: 2,
                patch: 3,
                pre: "rc.1".into()
            }
        );
        assert_eq!(m.version.text(), "1.2.3-rc.1");
        assert_eq!(
            (m.build, m.security_version, m.onbf_format),
            (42, 7, (1, 0))
        );
    }

    #[test]
    fn release_version_without_pre_release() {
        let m = parse(&variant(r#""1.2.3-rc.1""#, r#""2.0.0""#)).unwrap();
        assert_eq!(m.version.text(), "2.0.0");
        assert!(m.version.pre.is_empty());
    }

    #[test]
    fn rejects_unknown_duplicate_missing_and_stray_keys() {
        assert!(
            error_of(&variant("build = 42", "build = 42\nchannel = \"x\""))
                .contains("unknown key `channel`")
        );
        assert!(
            error_of(&variant("build = 42", "build = 42\nbuild = 43"))
                .contains("duplicate key `build`")
        );
        assert!(error_of(&variant("build = 42\n", "")).contains("missing key `build`"));
        assert!(error_of("version = \"1.0.0\"\n").contains("outside any section"));
    }

    #[test]
    fn rejects_unknown_and_duplicate_sections() {
        assert!(
            error_of(&variant("[compatibility]", "[extra]")).contains("unknown section [extra]")
        );
        assert!(error_of(&format!("{VALID}\n[release]\n")).contains("duplicate section [release]"));
        assert!(
            error_of(&variant("[compatibility]", "[compatibility"))
                .contains("unterminated section")
        );
    }

    #[test]
    fn rejects_bad_semver() {
        for (bad, why) in [
            ("1.2", "MAJOR.MINOR.PATCH"),
            ("1.2.3.4", "MAJOR.MINOR.PATCH"),
            ("01.2.3", "leading zero"),
            ("1.2.3+build.5", "build metadata"),
            ("1.2.3-", "empty pre-release"),
            ("1.2.3-rc..1", "empty pre-release"),
            ("1.2.3-rc.01", "leading zero in numeric pre-release"),
            ("1.2.3-rc_1", "invalid character"),
            ("1.x.3", "non-negative integer"),
        ] {
            let e = error_of(&variant(r#""1.2.3-rc.1""#, &format!("{bad:?}")));
            assert!(e.contains(why), "{bad}: {e}");
            assert!(e.starts_with("origin-version.toml:4:"), "{bad}: {e}");
        }
        // Hyphens are valid inside pre-release identifiers.
        assert!(parse(&variant(r#""1.2.3-rc.1""#, r#""1.2.3-dev-x.2""#)).is_ok());
    }

    #[test]
    fn rejects_bad_values() {
        assert!(error_of(&variant("build = 42", "build = 042")).contains("leading zero"));
        assert!(error_of(&variant("build = 42", "build = -1")).contains("non-negative integer"));
        assert!(error_of(&variant("build = 42", "build = 4_2")).contains("unexpected text"));
        assert!(error_of(&variant("build = 42", "build = \"42\"")).contains("must be an integer"));
        assert!(
            error_of(&variant("build = 42", "build = 18446744073709551616")).contains("64 bits")
        );
        assert!(
            error_of(&variant(
                "security-version = 7",
                "security-version = 4294967296"
            ))
            .contains("32 bits")
        );
        assert!(error_of(&variant(r#""1.0""#, "1")).contains("must be a string"));
        assert!(error_of(&variant(r#""1.0""#, r#""1.0.0""#)).contains("non-negative integer"));
        assert!(error_of(&variant(r#""1.0""#, r#""65536.0""#)).contains("16 bits"));
        assert!(error_of(&variant(r#""1.2.3-rc.1""#, r#""1.2.3"#)).contains("unterminated string"));
        assert!(error_of(&variant(r#""1.2.3-rc.1""#, r#""1.2.3\n""#)).contains("escape"));
        assert!(error_of(&variant("build = 42", "build = 42 extra")).contains("unexpected text"));
        assert!(error_of(&variant("build = 42", "build")).contains("expected `key = value`"));
    }
}
